SELECT id, interval_code, candle_open_time, decision, original_decision, final_entry_allowed, primary_blocking_stage, confluence_status, confluence_higher_interval, confluence_higher_decision, btc_context_status, derivatives_status, liquidity_status, LEFT(decision_path, 4000) AS decision_path, LEFT(final_decision_explanation, 1500) AS final_explanation FROM crypto_ai.trade_signal WHERE id IN (176529,176655,176710) ORDER BY id;